macro.command:
// Cloak of Displacement — item macro (2024 rules)
// Transfer effect with macroRepeat: startEveryTurn
// Creates a non-transfer "Displaced" effect with grants.disadvantage.attack.all
// and isDamaged special duration. When damaged, midi-qol removes that effect.
// At the start of each turn, this macro re-creates it if missing and speed > 0.

const DISPLACED_NAME = "Displaced";
const lastArg = args[args.length - 1];

function hasDisplacedEffect() {
  return actor.appliedEffects.find(e => e.name === DISPLACED_NAME && e.origin === macroItem.uuid);
}

function hasSpeed() {
  const speed = actor.system.attributes?.movement;
  if (!speed) return false;
  return (speed.walk || 0) > 0 || (speed.fly || 0) > 0 || (speed.swim || 0) > 0 || (speed.climb || 0) > 0 || (speed.burrow || 0) > 0;
}

async function createDisplacedEffect() {
  const effectData = {
    name: DISPLACED_NAME,
    img: "icons/magic/control/silhouette-hold-beam-blue.webp",
    origin: macroItem.uuid,
    changes: [
      { key: "flags.midi-qol.grants.disadvantage.attack.all", mode: 0, value: "1", priority: 20 }
    ],
    flags: {
      dae: {
        specialDuration: ["isDamaged"],
        stackable: "noneName"
      }
    },
    description: "<p>Creatures have Disadvantage on attack rolls against you (Cloak of Displacement). Removed when you take damage.</p>"
  };
  await actor.createEmbeddedDocuments("ActiveEffect", [effectData]);
}

async function removeDisplacedEffect() {
  const existing = hasDisplacedEffect();
  if (existing) await existing.delete();
}

if (args[0] === "on") {
  if (hasSpeed() && !hasDisplacedEffect()) await createDisplacedEffect();
  return;
}

if (args[0] === "off") {
  await removeDisplacedEffect();
  return;
}

if (args[0] === "each" && lastArg.turn === "startTurn") {
  if (!hasSpeed()) {
    await removeDisplacedEffect();
    return;
  }
  if (!hasDisplacedEffect()) {
    await createDisplacedEffect();
    ChatMessage.create({
      content: `<p><strong>${actor.name}'s</strong> Cloak of Displacement shimmers back to life.</p>`,
      speaker: ChatMessage.getSpeaker({ actor })
    });
  }
}
